import { loadFont } from "@remotion/google-fonts/Inter";
import React, { createContext, useContext } from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// GUIA PMMG · motion v1 (16/10/2026). Roteiro v2 aprovado pelo o diretor: sem narração, só texto na tela + trilha e efeitos
// (tools/make_audio_guiapmmg.py). As 12 cenas são as da prévia (GuiaPmmgPrevia.tsx), agora animadas.
// Jeito motion: só chegou o roteiro e o logo do site. Telas da plataforma desenhadas, com "telas ilustrativas".
// Identidade de guiapmmg.com.br: marinho #0B132B, dourado #FBBF24, fio vermelho #E11D48, Inter 800, águia com triângulo.
// O texto entra com impulso e fica parado; o movimento contínuo (câmera) fica nos objetos: giroflex, cartões, celular, telas.
// Abertura: giroflex vermelho e azul + escudo dourado genérico (não é o brasão da PMMG).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const GPM_FPS = 30;
export const GPM_FRAMES = Math.round(46 * GPM_FPS);
export const GPM2_FRAMES = Math.round(47.0 * GPM_FPS);

// v2 (com narração): algumas cenas mudam a ordem das entradas para acompanhar a fala
const V2 = createContext(false);
// v2: tempo das cenas → tempo real do vídeo. Câmera e fundo andam no tempo real, para nunca parar nos trechos
// em que o tempo das cenas segura (entre uma fala e outra); as entradas seguem o tempo das cenas, presas à fala.
const REAL = createContext<((e: number) => number) | null>(null);
// 4:5 (feed): o quadro 9:16 entra escalado; o fundo de cada cena se estende para fora (sombra cheia da mesma cor)
// e a legenda "telas ilustrativas" sobe para não cair no corte de baixo
const FEED = createContext(false);
const sangra = (c: string) => `0 0 0 900px ${c}`;
// no 4:5, camada de efeito (luz, clarão, brilho do fundo, troca de cena) cobre o quadro inteiro, não só o 9:16 reduzido
const FORA = 200;
// (AbsoluteFill já traz width/height 100%: sem trocar os dois, a camada só cresceria para a esquerda e para cima)
const cheio = (feed: boolean): React.CSSProperties => (feed ? { top: -FORA, left: -FORA, width: `calc(100% + ${2 * FORA}px)`, height: `calc(100% + ${2 * FORA}px)` } : {});
const useReal = () => {
  const inv = useContext(REAL);
  const tv = useCurrentFrame() / GPM_FPS;
  return inv ? { tv, at: inv } : null;
};
// v2: objeto que voa até chegar na palavra (começa pre s antes, no tempo real); na v1, a entrada normal de d s
const useFly = () => {
  const r = useReal();
  return (te: number, at: number, pre: number, d: number) => (r ? io(r.tv, r.at(at) - pre, r.at(at) + d * 0.5) : k(te, at, d));
};

const NAVY = "#0B132B";
const NAVY2 = "#16203D";
const NAVY3 = "#24304F";
const GOLD = "#FBBF24";
const RED = "#E11D48";
const BLUE = "#2563EB";
const WHITE = "#FFFFFF";
const PAPER = "#F8FAFC";
const LINE = "#E2E8F0";
const GREY = "#9CA3AF";
const GREEN = "#16A34A";
const SHADOW = "0 34px 80px rgba(11,19,43,0.22), 0 6px 18px rgba(11,19,43,0.10)";
const SHADOW_D = "0 40px 90px rgba(0,0,0,0.45)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
// impulso curto que volta a zero (o objeto "sente" a entrada)
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const o2 = (e: number) => Math.min(1, e * 2);

// trocas de cena (s)
const T = [0, 4, 8, 11, 14, 18, 22, 26, 30, 34, 38, 41];

// ───────── texto: entra com impulso (escala com sobra + desfoque) e fica parado no lugar ─────────
const enter = (t: number, at: number): React.CSSProperties => {
  const e = k(t, at, 0.4);
  const s = pop(t, at, 0.5);
  return { opacity: Math.min(1, e * 1.7), filter: `blur(${((1 - e) * 14).toFixed(1)}px)`, transform: `scale(${(0.82 + 0.18 * s).toFixed(4)})` };
};

type Ln = [string, number];
// trecho entre * fica dourado (fundo escuro) ou em faixa dourada (fundo claro)
const Title: React.FC<{ t: number; lines: Ln[]; top: number; size?: number; dark?: boolean; color?: string; weight?: number }> = ({ t, lines, top, size = 100, dark = true, color, weight = 800 }) => (
  <div style={{ position: "absolute", top, left: 120, right: 120, display: "flex", flexDirection: "column", alignItems: "center" }}>
    {lines.map(([l, at], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.035em", textAlign: "center", whiteSpace: "nowrap", color: color ?? (dark ? WHITE : NAVY), ...enter(t, at) }}>
        {l.split("*").map((p, j) =>
          j % 2 ? (
            dark ? (
              <span key={j} style={{ color: GOLD }}>{p}</span>
            ) : (
              <span key={j} style={{ background: GOLD, color: NAVY, padding: "0 0.22em 0.04em", borderRadius: "0.18em" }}>{p}</span>
            )
          ) : (
            <span key={j}>{p}</span>
          ),
        )}
      </div>
    ))}
  </div>
);

const Eyebrow: React.FC<{ t: number; at: number; children: React.ReactNode; top: number }> = ({ t, at, children, top }) => (
  <div style={{ position: "absolute", top, left: 0, right: 0, display: "flex", justifyContent: "center", alignItems: "center", gap: 22, ...enter(t, at) }}>
    <div style={{ width: 64 * k(t, at + 0.1, 0.5), height: 5, background: RED, borderRadius: 3 }} />
    <div style={{ fontFamily: F, fontWeight: 700, fontSize: 30, letterSpacing: "0.12em", color: GREY }}>{children}</div>
  </div>
);

const Ilustrativa: React.FC<{ t: number; at: number; dark?: boolean }> = ({ t, at, dark }) => (
  <div style={{ position: "absolute", bottom: useContext(FEED) ? 200 : 90, left: 0, right: 0, textAlign: "center", fontFamily: F, fontWeight: 500, fontSize: 24, color: dark ? "#5B6685" : "#A0AEC0", opacity: k(t, at + 0.6, 0.6) }}>telas ilustrativas</div>
);

// fundo liso; no escuro, um degradê suave que respira devagar atrás do centro
const Bg: React.FC<{ t: number; dark?: boolean; children: React.ReactNode }> = ({ t: te, dark = true, children }) => {
  const t = useReal()?.tv ?? te;
  const feed = useContext(FEED);
  return (
  <AbsoluteFill style={{ background: dark ? NAVY : PAPER, overflow: feed ? "visible" : "hidden", boxShadow: sangra(dark ? NAVY : PAPER) }}>
    {dark ? <AbsoluteFill style={{ ...cheio(feed), opacity: 0.8 + 0.2 * Math.sin(t * 1.4), background: `radial-gradient(ellipse 70% 45% at 50% ${(56 + 3 * Math.sin(t * 0.7)).toFixed(2)}%, #1A2850 0%, rgba(11,19,43,0) 70%)` }} /> : null}
    {children}
  </AbsoluteFill>
  );
};

// câmera dos objetos: anda a cena inteira (de a até o fim da troca seguinte) e sente cada entrada
type Cam = { s: [number, number]; x?: [number, number]; y?: [number, number]; r?: [number, number]; o?: string };
// foc = [início, escala, x, y, volta?]: no meio da cena a câmera aproxima no detalhe que a frase cita (e pode voltar).
// O ponto fica no topo dos objetos, para a aproximação crescer para baixo e nunca subir no título.
type Foc = [number, number, number, number, number?];
const Stage: React.FC<{ t: number; a: number; b: number; cam: Cam; kicks?: number[]; foc?: Foc; children: React.ReactNode }> = ({ t: te, a, b, cam, kicks = [], foc, children }) => {
  // na v2 os tempos (da cena) viram tempo real e a câmera anda no relógio do vídeo
  const r = useReal();
  const t = r ? r.tv : te;
  const R = r ? r.at : (x: number) => x;
  const p = lin(t, R(a), R(b + 0.45));
  const v = (x?: [number, number]) => (x ? x[0] + (x[1] - x[0]) * p : 0);
  const kick = kicks.reduce((s, at) => s + bump(t, R(at), 0.35), 0);
  const fe = foc ? io(t, R(foc[0]), Math.max(R(foc[0] + 0.9), R(foc[0]) + 0.6)) - (foc[4] ? io(t, R(foc[4]), Math.max(R(foc[4] + 0.7), R(foc[4]) + 0.5)) : 0) : 0;
  const [fx, fy] = foc ? [foc[2], foc[3]] : [540, 1100];
  return (
    <AbsoluteFill style={{ transformOrigin: cam.o ?? "540px 1100px", transform: `translate(${v(cam.x).toFixed(2)}px, ${v(cam.y).toFixed(2)}px) scale(${(v(cam.s) * (1 + 0.022 * kick)).toFixed(4)}) rotate(${v(cam.r).toFixed(3)}deg)` }}>
      <AbsoluteFill style={{ transformOrigin: `${fx}px ${fy}px`, transform: `scale(${(1 + ((foc ? foc[1] : 1) - 1) * fe).toFixed(4)})` }}>
        {children}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoBook: Ico = ({ s, c }) => sv(s, c, <><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H6.5A2.5 2.5 0 0 0 4 20.5z" /><path d="M4 20.5A2.5 2.5 0 0 0 6.5 23H20v-5" /></>);
const IcoPdf: Ico = ({ s, c }) => sv(s, c, <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><path d="M14 2v6h6" /></>);
const IcoGrid: Ico = ({ s, c }) => sv(s, c, <><rect x="3" y="3" width="18" height="18" rx="2" /><path d="M3 9h18M3 15h18M9 3v18M15 3v18" /></>);
const IcoNote: Ico = ({ s, c }) => sv(s, c, <><rect x="5" y="2.5" width="15" height="19" rx="2" /><path d="M9 7h7M9 11h7M9 15h4M3 6h3M3 12h3M3 18h3" /></>);
const IcoCheck: Ico = ({ s, c, w = 3 }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, w);
const IcoBell: Ico = ({ s, c }) => sv(s, c, <><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9" /><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0" /></>);
const IcoArrow: Ico = ({ s, c, w = 2.6 }) => sv(s, c, <path d="M4 12h15M13 6l6 6-6 6" />, w);
const IcoTrophy: Ico = ({ s, c }) => sv(s, c, <><path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0z" /><path d="M7 6H4a3 3 0 0 0 3 4M17 6h3a3 3 0 0 1-3 4" /></>);

// relógio com ponteiros girando
const Clock: React.FC<{ s: number; t: number }> = ({ s, t }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={GOLD} strokeWidth={2.2} strokeLinecap="round">
    <circle cx="12" cy="12" r="9.5" />
    <line x1="12" y1="12" x2="12" y2="7" transform={`rotate(${(t * 90).toFixed(1)} 12 12)`} />
    <line x1="12" y1="12" x2="12" y2="4.5" transform={`rotate(${(t * 720).toFixed(1)} 12 12)`} />
  </svg>
);

// triângulo vermelho do logo, usado como marcador
const Tri: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s * 0.88} viewBox="0 0 100 88">
    <path d="M50 4 L96 84 L4 84 Z" fill={RED} stroke={NAVY} strokeWidth={5} strokeLinejoin="round" />
  </svg>
);

// ───────── celular ─────────
const Phone: React.FC<{ w: number; children: React.ReactNode }> = ({ w, children }) => (
  <div style={{ width: w, height: w * 2.05, borderRadius: w * 0.14, background: NAVY, padding: w * 0.035, boxSizing: "border-box", boxShadow: SHADOW }}>
    <div style={{ width: "100%", height: "100%", borderRadius: w * 0.11, background: PAPER, overflow: "hidden", position: "relative" }}>
      <div style={{ position: "absolute", top: w * 0.03, left: "50%", marginLeft: -w * 0.14, width: w * 0.28, height: w * 0.07, borderRadius: w, background: NAVY }} />
      {children}
    </div>
  </div>
);

// ═════════ 1 · gancho de polícia: giroflex + escudo genérico ═════════
const Giroflex: React.FC<{ w: number; r: number; b: number }> = ({ w, r, b }) => (
  <div style={{ position: "relative", width: w, height: w * 0.2 }}>
    <div style={{ position: "absolute", left: -w * 0.25, top: -w * 0.45, width: w * 0.9, height: w * 1.1, opacity: 0.25 + 0.75 * r, background: "radial-gradient(circle, rgba(225,29,72,0.55) 0%, rgba(225,29,72,0) 65%)" }} />
    <div style={{ position: "absolute", right: -w * 0.25, top: -w * 0.45, width: w * 0.9, height: w * 1.1, opacity: 0.25 + 0.75 * b, background: "radial-gradient(circle, rgba(37,99,235,0.6) 0%, rgba(37,99,235,0) 65%)" }} />
    <div style={{ position: "absolute", inset: 0, borderRadius: w * 0.1, background: NAVY2, border: `4px solid ${NAVY3}`, display: "flex", padding: w * 0.025, gap: w * 0.02 }}>
      <div style={{ flex: 1, borderRadius: w * 0.07, background: "#4A1022", position: "relative" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: w * 0.07, opacity: 0.3 + 0.7 * r, background: `linear-gradient(180deg, #FF6688, ${RED})`, boxShadow: `0 0 ${(20 + 60 * r).toFixed(0)}px ${RED}` }} />
      </div>
      <div style={{ width: w * 0.12, borderRadius: w * 0.04, background: NAVY3 }} />
      <div style={{ flex: 1, borderRadius: w * 0.07, background: "#0F2357", position: "relative" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: w * 0.07, opacity: 0.3 + 0.7 * b, background: `linear-gradient(180deg, #6B98FF, ${BLUE})`, boxShadow: `0 0 ${(20 + 60 * b).toFixed(0)}px ${BLUE}` }} />
      </div>
    </div>
  </div>
);
const Escudo: React.FC<{ s: number; star: number }> = ({ s, star }) => (
  <svg width={s} height={s * 1.15} viewBox="0 0 100 115" style={{ overflow: "visible" }}>
    <path d="M50 4 L92 18 V56 C92 82 72 100 50 111 C28 100 8 82 8 56 V18 Z" fill={NAVY2} stroke={GOLD} strokeWidth={6} strokeLinejoin="round" />
    <g transform={`translate(50 55) rotate(${((1 - star) * -216).toFixed(1)}) scale(${star.toFixed(3)}) translate(-50 -55)`}>
      <path d="M50 30 l7.2 14.6 16.1 2.3-11.6 11.4 2.7 16-14.4-7.6-14.4 7.6 2.7-16-11.6-11.4 16.1-2.3z" fill={GOLD} />
    </g>
  </svg>
);
const S1: React.FC<{ t: number }> = ({ t }) => {
  const v2 = useContext(V2);
  if (v2) return <S1V2 />;
  const ph = (t * 2 * Math.PI) / 0.62;
  const r = Math.max(0, Math.cos(ph)) ** 0.7;
  const b = Math.max(0, -Math.cos(ph)) ** 0.7;
  const g = k(t, 0, 0.5);
  const sh = pop(t, 2.05, 0.6);
  const star = pop(t, 2.3, 0.7);
  return (
    <Bg t={t}>
      {/* a luz do giroflex pinta o fundo, um lado de cada vez */}
      <AbsoluteFill style={{ opacity: 0.5 * r * g, background: "radial-gradient(ellipse 65% 42% at 22% 20%, rgba(225,29,72,1) 0%, rgba(225,29,72,0) 70%)" }} />
      <AbsoluteFill style={{ opacity: 0.55 * b * g, background: "radial-gradient(ellipse 65% 42% at 78% 20%, rgba(37,99,235,1) 0%, rgba(37,99,235,0) 70%)" }} />
      <Stage t={t} a={T[0]} b={T[1]} cam={{ s: [1.0, 1.07], y: [0, 24], o: "540px 950px" }} kicks={[1.4]}>
        <div style={{ position: "absolute", top: 330, left: 0, right: 0, display: "flex", justifyContent: "center", opacity: o2(g), transform: `scale(${(1.4 - 0.4 * pop(t, 0, 0.55)).toFixed(4)})` }}>
          <Giroflex w={620} r={r} b={b} />
        </div>
        <div style={{ position: "absolute", top: 1190, left: 0, right: 0, display: "flex", justifyContent: "center", opacity: o2(sh), transform: `translateY(${((1 - sh) * 520 + Math.sin(t * 2.2) * 10).toFixed(1)}px) scale(${(0.55 + 0.45 * sh).toFixed(4)}) rotate(${((1 - sh) * 18).toFixed(2)}deg)` }}>
          <div style={{ position: "absolute", top: 60, width: 520, height: 520, borderRadius: 600, background: "radial-gradient(circle, rgba(251,191,36,0.22) 0%, rgba(251,191,36,0) 65%)", opacity: sh * (0.8 + 0.2 * Math.sin(t * 3)) }} />
          <Escudo s={430} star={star} />
        </div>
      </Stage>
      <div style={{ position: "absolute", top: 610, left: 0, right: 0, textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: 64, color: GOLD, letterSpacing: "-0.02em", ...enter(t, 0.3) }}>Concurseiro,</div>
      <Title t={t} top={720} lines={[["nunca foi tão fácil", 0.75], ["estudar para a", 1.0]]} size={104} />
      {/* PMMG! entra como batida: grande e assenta */}
      <div style={{ position: "absolute", top: 720 + 2 * 114.4, left: 0, right: 0, textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: 104, lineHeight: 1.1, letterSpacing: "-0.035em", color: GOLD, opacity: o2(k(t, 1.35, 0.25)), transform: `scale(${(1.7 - 0.7 * k(t, 1.35, 0.35)).toFixed(4)})` }}>PMMG!</div>
    </Bg>
  );
};

// v2 (pedido do cliente: abertura muito mais dinâmica, com o distintivo da PMMG que ele mandou em src/logo-inicio.png).
// Corre no tempo real do vídeo. O distintivo bate no centro no 1º quadro e sobe para o topo; cada palavra da fala ocupa a tela sozinha, entra de um jeito
// diferente e sai empurrada pela seguinte; a luz vermelha/azul do giroflex pisca a cada palavra e a câmera dá um tranco.
const W1: [string, number][] = [["Concurseiro,", 0.36], ["nunca", 1.34], ["foi", 1.72], ["tão", 2.06], ["fácil", 2.46], ["estudar", 2.92], ["para a", 3.46], ["PMMG!", 3.68]];
const PM = W1[7][1];
const S1_FIM = 4.64;
// inversão de cor (pedido): nessas palavras a tela vira, em corte seco, fundo branco e letra marinho
const INVERTE = new Set([1, 3, 5]);
// entrada de cada palavra: [x, y, escala, giro] de onde ela vem
const VEM: [number, number, number, number][] = [[0, 0, 2.4, 0], [0, -420, 1, 0], [520, 0, 1, 8], [0, 0, 0.2, -10], [-560, 0, 1, -6], [0, 460, 1, 0], [0, 0, 1.8, 12], [0, 0, 3.2, 0]];
const S1V2: React.FC = () => {
  const t = useCurrentFrame() / GPM_FPS;
  const feed = useContext(FEED);
  const hits = W1.map(([, at]) => at);
  // giroflex: pisca sozinho e estoura a cada palavra, alternando vermelho e azul
  const ph = (t * 2 * Math.PI) / 0.42;
  const hitR = hits.reduce((s, at, i) => s + (i % 2 === 0 ? bump(t, at, 0.45) : 0), 0);
  const hitB = hits.reduce((s, at, i) => s + (i % 2 === 1 ? bump(t, at, 0.45) : 0), 0);
  const r = 0.35 * Math.max(0, Math.cos(ph)) ** 0.7 + 0.9 * hitR;
  const b = 0.35 * Math.max(0, -Math.cos(ph)) ** 0.7 + 0.9 * hitB;
  const flash = bump(t, 0, 0.25) + 0.7 * bump(t, PM, 0.35);
  const cur = W1.reduce((c, [, at], i) => (t >= at ? i : c), -1);
  const inv = INVERTE.has(cur);
  // câmera: aproxima o tempo todo e dá um tranco em cada palavra
  const shake = hits.reduce((s, at, i) => s + bump(t, at, 0.28) * (i === 7 ? 2 : 1), 0) + 1.5 * bump(t, 0, 0.3);
  const cam = `translate(${(Math.sin(t * 53) * 9 * shake).toFixed(1)}px, ${(Math.cos(t * 47) * 9 * shake).toFixed(1)}px) scale(${(1 + 0.06 * lin(t, 0, S1_FIM) + 0.025 * shake).toFixed(4)}) rotate(${(Math.sin(t * 1.3) * 0.8).toFixed(3)}deg)`;
  // águia: bate grande no centro, sobe em 0,08–0,34 s (antes de "Concurseiro," assentar) e pulsa no PMMG!
  const ea = k(t, 0, 0.14);
  const up = k(t, 0.08, 0.26);
  const eScale = (2.3 - 1.0 * ea) * (1 - 0.35 * up) * (1 + 0.18 * bump(t, PM, 0.4));
  const eY = 960 - 420 * up;
  return (
    <AbsoluteFill style={{ background: inv ? WHITE : NAVY, overflow: feed ? "visible" : "hidden", boxShadow: sangra(inv ? WHITE : NAVY) }}>
      <AbsoluteFill style={{ ...cheio(feed), opacity: inv ? 0 : Math.min(1, r), background: "radial-gradient(ellipse 75% 50% at 15% 25%, rgba(225,29,72,0.95) 0%, rgba(225,29,72,0) 70%)" }} />
      <AbsoluteFill style={{ ...cheio(feed), opacity: inv ? 0 : Math.min(1, b), background: "radial-gradient(ellipse 75% 50% at 85% 25%, rgba(37,99,235,1) 0%, rgba(37,99,235,0) 70%)" }} />
      <AbsoluteFill style={{ transform: cam }}>
