const SCENES: [number, React.FC<{ t: number }>, ((p: number) => string) | null][] = [
  [T[0], S1, null],
  [T[1], S2, (p) => `circle(${(p * 130).toFixed(1)}% at 50% 20%)`],
  [T[2], S3, (p) => `inset(${((1 - p) * 100).toFixed(2)}% 0 0 0)`],
  [T[3], S4, null],
  [T[4], S5, (p) => `polygon(0 0, ${(p * 170).toFixed(1)}% 0, ${(p * 170 - 60).toFixed(1)}% 100%, 0 100%)`],
  [T[5], S6, (p) => `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)`],
  [T[6], S7, (p) => `circle(${(p * 150).toFixed(1)}% at 50% 100%)`],
  [T[7], S8, (p) => `inset(0 0 0 ${((1 - p) * 100).toFixed(2)}%)`],
  [T[8], S9, (p) => `polygon(${(100 - p * 170).toFixed(1)}% 0, 100% 0, 100% 100%, ${(160 - p * 170).toFixed(1)}% 100%)`],
  [T[9], S10, (p) => `inset(${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}% 0)`],
  [T[10], S11, (p) => `inset(0 ${((1 - p) * 100).toFixed(2)}% 0 0)`],
  [T[11], S12, (p) => `circle(${(p * 120).toFixed(1)}% at 50% 50%)`],
];
const TR = 0.45;

const Core: React.FC<{ t: number }> = ({ t }) => {
  const feed = useContext(FEED);
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {SCENES.map(([at, S, clip], i) => {
        const next = SCENES[i + 1];
        const end = next ? next[0] + (next[2] ? TR : 0) : 1e9;
        if (t < at || t >= end) return null;
        const p = clip ? interpolate(t, [at, at + TR], [0, 1], { ...cl, easing: INOUT }) : 1;
        return (
          <AbsoluteFill key={i} style={{ ...cheio(feed), ...(clip && p < 1 ? { clipPath: clip(p) } : {}) }}>
            {feed ? (
              <div style={{ position: "absolute", left: FORA, top: FORA, width: 1080, height: 1920 }}>
                <S t={t} />
              </div>
            ) : (
              <S t={t} />
            )}
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

