  [0, 0], [0.36, 0.3], [1.34, 0.75], [2.92, 1], [3.68, 1.35], [3.88, 2.05], [4.64, 4], [4.81, 4.3],
  [5.37, 4.55], [6.21, 4.9], [6.81, 5.45], [7.41, 6], [7.89, 6.55], [8.73, 8], [9.03, 8.15], [9.89, 8.4],
  [10.53, 8.65], [10.79, 9.3], [11.55, 11], [11.69, 11.1], [12.62, 11.85], [13.24, 12.4], [13.96, 14], [14.11, 14.25],
  [15.15, 14.5], [15.77, 16], [16.26, 18], [16.39, 18.15], [16.96, 18.3], [18.36, 19.15], [18.43, 19.3], [19.17, 19.6],
  [19.87, 19.9], [20.46, 21], [20.66, 22], [20.77, 22.15], [21.2, 22.4], [21.44, 22.85], [21.78, 23.45], [22.13, 24.05],
  [22.92, 26], [23.25, 26.15], [23.63, 26.4], [24.22, 26.65], [24.8, 27.9], [25.59, 29.1], [25.88, 30], [26.07, 30.15],
  [26.58, 30.4], [26.79, 30.6], [27.05, 31.05], [27.77, 31.45], [27.95, 31.85], [29.35, 32.25], [29.81, 32.75], [30.34, 34],
  [30.47, 34.15], [30.79, 34.4], [31.78, 35.25], [32.72, 35.3], [33.15, 35.55], [33.25, 35.6], [33.84, 36.2], [34.82, 38],
  [35.22, 38.12], [36.38, 38.75], [37.05, 39.85], [37.42, 41], [37.49, 41.1], [37.97, 41.85], [38.64, 42.15], [40.29, 42.6],
  [40.86, 43.05], [42.09, 43.4], [45.34, 44.3], [47, 46],
];
const W2 = (() => {
  const w: [number, number][] = [];
  GPM2_EV.forEach(([n, e], i) => {
    w.push([n, e]);
    const nx = GPM2_EV[i + 1];
    if (!nx) return;
    const d = Math.min(0.55, nx[0] - n - 0.02, nx[1] - e - 0.02);
    if (d > 0.05) w.push([n + d, e + d]);
  });
  return w;
})();
export const gpm2Tempo = (tv: number) => interpolate(tv, W2.map((x) => x[0]), W2.map((x) => x[1]), cl);
const gpm2Real = (e: number) => interpolate(e, W2.map((x) => x[1]), W2.map((x) => x[0]), { extrapolateLeft: "clamp", extrapolateRight: "extend" });

export const GuiaPmmgV2: React.FC = () => (
  <V2.Provider value>
    <REAL.Provider value={gpm2Real}>
      <Core t={gpm2Tempo(useCurrentFrame() / GPM_FPS)} />
    </REAL.Provider>
  </V2.Provider>
);

// 4:5 (1080×1350) para o feed: o 9:16 inteiro a 78%, centrado; corta só a faixa vazia de cima e de baixo
export const GPM_FEED_ESCALA = 0.78;
export const GuiaPmmgV2Feed: React.FC = () => (
  <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
    <FEED.Provider value>
      <div style={{ position: "absolute", width: 1080, height: 1920, left: 0, top: (1350 - 1920) / 2, transform: `scale(${GPM_FEED_ESCALA})`, transformOrigin: "540px 960px" }}>
        <GuiaPmmgV2 />
      </div>
    </FEED.Provider>
  </AbsoluteFill>
);

